from pathlib import Path
root=Path(__file__).resolve().parents[1];review=root/'film/output/delivery-optimized/review';review.mkdir(parents=True,exist_ok=True)
for name in ['kanreki-drafting','kanreki-search','kanreki-profiles-r03']:
 for label,path in [('original',root/'media-originals/webm-2026-11-18'/f'{name}.webm'),('optimized',root/'public/media'/f'{name}.webm')]:
  link=review/f'{label}-{name}.webm'
  if not link.exists():link.symlink_to(path)
(review/'_headers').write_text("/*\n  X-Robots-Tag: noindex\n  Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; media-src 'self'; object-src 'none'; frame-ancestors 'none'\n")
(review/'404.html').write_text('<h1>Not found</h1>')
(review/'index.html').write_text('''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>kanreki | WebM delivery review</title><style>body{font:16px system-ui;color:#151517;background:white;margin:32px}button{background:#151517;color:white;border:0;border-radius:24px;padding:12px 20px;margin:8px;cursor:pointer}.films{display:grid;grid-template-columns:1fr 1fr;gap:16px}video{width:100%;border-radius:12px}h1{font-size:24px}p{color:#77777c}output{display:block;font-variant-numeric:tabular-nums}@media(max-width:700px){.films{grid-template-columns:1fr}}</style><script src="/review.js" defer></script></head><body><h1>kanreki | WebM delivery review</h1><p>Original on the left. Optimized delivery on the right. Both retain 1080p, 60 fps and the complete frame sequence.</p><nav><button data-film="kanreki-drafting">review drafting</button><button data-film="kanreki-search">review search</button><button data-film="kanreki-profiles-r03">review profiles</button><button id="play">play both</button><button id="pause">pause both</button></nav><div class="films"><section><h2>original</h2><video id="original" controls muted loop playsinline></video><output id="original-state"></output></section><section><h2>optimized delivery</h2><video id="optimized" controls muted loop playsinline></video><output id="optimized-state"></output></section></div></body></html>''')
(review/'review.js').write_text("""const videos=[...document.querySelectorAll('video')];let previous=[0,0],loops=[0,0];for(const button of document.querySelectorAll('[data-film]'))button.onclick=()=>{previous=[0,0];loops=[0,0];document.body.dataset.film=button.dataset.film;videos.forEach(video=>{video.pause();video.src='/'+video.id+'-'+button.dataset.film+'.webm';video.load();});};document.querySelector('#play').onclick=()=>videos.forEach(video=>video.play().catch(error=>document.querySelector('#'+video.id+'-state').textContent=error.message));document.querySelector('#pause').onclick=()=>videos.forEach(video=>video.pause());videos.forEach((video,i)=>{video.ontimeupdate=()=>{if(previous[i]>video.duration*.75&&video.currentTime<video.duration*.25)loops[i]++;previous[i]=video.currentTime;document.querySelector('#'+video.id+'-state').textContent=video.currentTime.toFixed(2)+' / '+video.duration.toFixed(2)+' s | completed loops: '+loops[i];video.dataset.loops=loops[i];};});""")
print(review)
